const SMI_MIN = -(2 ** 31);
const SMI_MAX = 2 ** 31 - 1;
function isSmi(v){
  return typeof v === 'number' && v >= SMI_MIN && v < SMI_MAX;
}

tasks.verify:
const cases = [
  [SMI_MAX, true], [SMI_MIN, true], [0, true], [-1, true],
  [2 ** 31, false], [SMI_MIN - 1, false], [3.5, false], [NaN, false],
];
let bad = '';
for (const [v, exp] of cases) { if (isSmi(v) !== exp) bad += v + '->' + isSmi(v) + ' '; }
const ok = bad === '';
console.log(ok ? 'PASS' : 'FAIL ' + bad);

